import { describe, it, expect } from "vitest";
import { deriveSkillTimeline } from "./deriveSkillTimeline";
import {
  type ConversationEvent,
  type UnionEventType,
  type EventMetadata,
  ConversationEventType,
} from "../../types";

function makeSkillEvent(
  overrides: Partial<ConversationEvent> & {
    conversationEventType: ConversationEventType;
    timestamp: string;
    originalTimestamp: number;
  },
): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: crypto.randomUUID(),
    actionText: "",
    name: "",
    slotValue: null,
    stepId: "",
    metadata: {} as EventMetadata,
    ...overrides,
  };
}

describe("deriveSkillTimeline", () => {
  it("returns entries in reverse chronological order (newest first)", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_b",
        timestamp: "2024-01-01T12:05:00Z",
        originalTimestamp: 1704110700,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(2);
    expect(result[0].skillId).toBe("skill_b");
    expect(result[1].skillId).toBe("skill_a");
  });

  it("marks activated skills as active", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(1);
    expect(result[0].type).toBe("skill");
    expect(result[0].status).toBe("active");
    expect(result[0].endTime).toBeUndefined();
  });

  it("pairs activation with completion and sets endTime", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillCompleted,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:45Z",
        originalTimestamp: 1704110445,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(1);
    expect(result[0].status).toBe("completed");
    expect(result[0].endTime).toEqual(new Date("2024-01-01T12:00:45Z"));
  });

  it("marks cancelled skills with endTime", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillCancelled,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:30Z",
        originalTimestamp: 1704110430,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(1);
    expect(result[0].status).toBe("cancelled");
    expect(result[0].endTime).toBeDefined();
  });

  it("marks interrupted skills without endTime", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillInterrupted,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(1);
    expect(result[0].status).toBe("interrupted");
    expect(result[0].endTime).toBeUndefined();
  });

  it("handles digression: interrupted → resumed transitions back to active", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillInterrupted,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_b",
        timestamp: "2024-01-01T12:01:10Z",
        originalTimestamp: 1704110470,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillCompleted,
        skillId: "skill_b",
        timestamp: "2024-01-01T12:02:00Z",
        originalTimestamp: 1704110520,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillResumed,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:02:10Z",
        originalTimestamp: 1704110530,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(2);
    const digression = result.find((entry) => entry.skillId === "skill_b");
    const resumed = result.find((entry) => entry.skillId === "skill_a");
    expect(digression?.status).toBe("completed");
    expect(resumed?.status).toBe("active");
  });

  it("creates block entries from ordered-block lifecycle events", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        id: "block-entered",
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "skill_a",
        blockId: "collect_details",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.OrderedBlockCompleted,
        skillId: "skill_a",
        blockId: "collect_details",
        timestamp: "2024-01-01T12:00:20Z",
        originalTimestamp: 1704110420,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(1);
    expect(result[0].id).toBe("block-entered");
    expect(result[0].type).toBe("block");
    expect(result[0].skillId).toBe("skill_a");
    expect(result[0].blockId).toBe("collect_details");
    expect(result[0].status).toBe("completed");
    expect(result[0].endTime).toEqual(new Date("2024-01-01T12:00:20Z"));
  });

  it("keeps block invocations of the same block id separate per skill", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "skill_a",
        blockId: "shared_block",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "skill_b",
        blockId: "shared_block",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.OrderedBlockCompleted,
        skillId: "skill_b",
        blockId: "shared_block",
        timestamp: "2024-01-01T12:02:00Z",
        originalTimestamp: 1704110520,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(2);
    expect(result.find((entry) => entry.skillId === "skill_a")?.status).toBe("active");
    expect(result.find((entry) => entry.skillId === "skill_b")?.status).toBe("completed");
  });

  it("handles multiple invocations of the same skill", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        id: "ev-1",
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillCompleted,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460,
      }),
      makeSkillEvent({
        id: "ev-2",
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:02:00Z",
        originalTimestamp: 1704110520,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(2);
    expect(result[0].id).toBe("ev-2");
    expect(result[0].status).toBe("active");
    expect(result[1].id).toBe("ev-1");
    expect(result[1].status).toBe("completed");
  });

  it("ignores historical Flow* compatibility events entirely", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.FlowStarted,
        flowId: "skill_a_main",
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        id: "skill-activated",
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400.0001,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.FlowCompleted,
        flowId: "skill_a_main",
        skillId: "skill_a",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillCompleted,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460.0001,
      }),
    ];

    const result = deriveSkillTimeline(events);

    expect(result).toHaveLength(1);
    expect(result[0].id).toBe("skill-activated");
    expect(result[0].type).toBe("skill");
    expect(result[0].status).toBe("completed");
  });

  it("returns no entries when only Flow* events are present", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.FlowStarted,
        flowId: "flow_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
      makeSkillEvent({
        conversationEventType: ConversationEventType.FlowInterrupted,
        flowId: "flow_a",
        timestamp: "2024-01-01T12:01:00Z",
        originalTimestamp: 1704110460,
      }),
    ];

    expect(deriveSkillTimeline(events)).toEqual([]);
  });

  it("resolves skill names from provided map", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "transfer_money",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
    ];

    const skillNames = new Map([["transfer_money", "Transfer Money"]]);
    const result = deriveSkillTimeline(events, skillNames);

    expect(result[0].flowName).toBe("Transfer Money");
  });

  it("ignores skill events without a skillId", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: undefined,
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
    ];

    expect(deriveSkillTimeline(events)).toEqual([]);
  });

  it("ignores completion events without a matching activation", () => {
    const events: UnionEventType[] = [
      makeSkillEvent({
        conversationEventType: ConversationEventType.SkillCompleted,
        skillId: "skill_a",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
      }),
    ];

    expect(deriveSkillTimeline(events)).toEqual([]);
  });

  it("ignores non-ConversationEvent events (Utterances)", () => {
    const events: UnionEventType[] = [
      {
        __typename: "Utterance",
        id: "1",
        type: "USER",
        text: "hello",
        timestamp: "2024-01-01T12:00:00Z",
        originalTimestamp: 1704110400,
        tokens: [],
        rephrase: false,
        rephrasePrompt: null,
        metadata: {} as EventMetadata,
      } as UnionEventType,
    ];

    expect(deriveSkillTimeline(events)).toEqual([]);
  });

  it("returns empty array for no events", () => {
    expect(deriveSkillTimeline([])).toEqual([]);
    expect(deriveSkillTimeline(undefined)).toEqual([]);
  });
});
